-- Textos rotos en perfil: la "o" con tilde de "nomina", "modulo" y la "i" con tilde de
-- "dia" aparecian como simbolos de dibujo de cajas (UTF-8 leido como CP437 y
-- guardado asi). Ya venia en el export de la base real del 3-sep-2026 (perfiles
-- 5, 6 y 8). Repara nombre y descripcion de TODOS los perfiles afectados, solo
-- las filas que contienen el caracter U+251C, por lo que es idempotente y no
-- toca descripciones editadas a mano. El archivo es ASCII puro (UNHEX) a
-- proposito: asi no depende del charset con que se pegue/importe en phpMyAdmin.

UPDATE perfil
SET per_descripcion = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(per_descripcion, CONVERT(UNHEX('E2949CC3BC') USING utf8), CONVERT(UNHEX('C381') USING utf8)), CONVERT(UNHEX('E2949CC3AB') USING utf8), CONVERT(UNHEX('C389') USING utf8)), CONVERT(UNHEX('E2949CC3AC') USING utf8), CONVERT(UNHEX('C38D') USING utf8)), CONVERT(UNHEX('E2949CC3A6') USING utf8), CONVERT(UNHEX('C391') USING utf8)), CONVERT(UNHEX('E2949CC3B4') USING utf8), CONVERT(UNHEX('C393') USING utf8)), CONVERT(UNHEX('E2949CC39C') USING utf8), CONVERT(UNHEX('C39A') USING utf8)), CONVERT(UNHEX('E2949CC3AD') USING utf8), CONVERT(UNHEX('C3A1') USING utf8)), CONVERT(UNHEX('E2949CE28C90') USING utf8), CONVERT(UNHEX('C3A9') USING utf8)), CONVERT(UNHEX('E2949CC2A1') USING utf8), CONVERT(UNHEX('C3AD') USING utf8)), CONVERT(UNHEX('E2949CE29692') USING utf8), CONVERT(UNHEX('C3B1') USING utf8)), CONVERT(UNHEX('E2949CE29482') USING utf8), CONVERT(UNHEX('C3B3') USING utf8)), CONVERT(UNHEX('E2949CE29591') USING utf8), CONVERT(UNHEX('C3BA') USING utf8)),
    per_nombre      = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(per_nombre, CONVERT(UNHEX('E2949CC3BC') USING utf8), CONVERT(UNHEX('C381') USING utf8)), CONVERT(UNHEX('E2949CC3AB') USING utf8), CONVERT(UNHEX('C389') USING utf8)), CONVERT(UNHEX('E2949CC3AC') USING utf8), CONVERT(UNHEX('C38D') USING utf8)), CONVERT(UNHEX('E2949CC3A6') USING utf8), CONVERT(UNHEX('C391') USING utf8)), CONVERT(UNHEX('E2949CC3B4') USING utf8), CONVERT(UNHEX('C393') USING utf8)), CONVERT(UNHEX('E2949CC39C') USING utf8), CONVERT(UNHEX('C39A') USING utf8)), CONVERT(UNHEX('E2949CC3AD') USING utf8), CONVERT(UNHEX('C3A1') USING utf8)), CONVERT(UNHEX('E2949CE28C90') USING utf8), CONVERT(UNHEX('C3A9') USING utf8)), CONVERT(UNHEX('E2949CC2A1') USING utf8), CONVERT(UNHEX('C3AD') USING utf8)), CONVERT(UNHEX('E2949CE29692') USING utf8), CONVERT(UNHEX('C3B1') USING utf8)), CONVERT(UNHEX('E2949CE29482') USING utf8), CONVERT(UNHEX('C3B3') USING utf8)), CONVERT(UNHEX('E2949CE29591') USING utf8), CONVERT(UNHEX('C3BA') USING utf8))
WHERE per_descripcion LIKE CONCAT('%', CONVERT(UNHEX('E2949C') USING utf8), '%')
   OR per_nombre      LIKE CONCAT('%', CONVERT(UNHEX('E2949C') USING utf8), '%');

-- Verificacion: debe devolver 0 filas.
SELECT per_id, per_nombre, per_descripcion FROM perfil
WHERE per_descripcion LIKE CONCAT('%', CONVERT(UNHEX('E2949C') USING utf8), '%')
   OR per_nombre      LIKE CONCAT('%', CONVERT(UNHEX('E2949C') USING utf8), '%');
